// AUTO-GENERATED by scripts/build-moonrise-views.mjs — do not edit by hand.
// Moonrise apartments (floor*100 + unit-position) that have a courtyard
// panorama. Apartments without a panorama are absent, so they're hidden
// from the floor dropdown in the courtyard view.
export const MOONRISE_VIEW_APTS = [2505, 2605, 2705, 2805, 3005, 3105, 3205, 3305, 3505]

const VIEW_SET = new Set(MOONRISE_VIEW_APTS)

// Apartment number for a floor + unit position (1-6).
export const aptNumber = (floor, position) => floor * 100 + position

// Public path to a panorama, or null when that apartment has no view.
export const viewImage = (floor, position) =>
  VIEW_SET.has(aptNumber(floor, position))
    ? `/unit/views/moonrise/${aptNumber(floor, position)}.webp`
    : null

// Floors (ascending) where the given unit position has a panorama.
export const floorsForPosition = (position) =>
  MOONRISE_VIEW_APTS.filter((a) => a % 100 === position).map((a) =>
    Math.floor(a / 100),
  )
